export type SearchCatalogParams = {
/**
 * @maxLength 200
 */
q?: string;
/**
 * Exact registry product identifier used with q=registration number.
 * @pattern ^[A-F0-9]{32}$
 */
productId?: string;
type?: SearchCatalogType;
/**
 * Flat keeps registry browse pagination. When omitted for a non-empty registry query, the server resolves grouped view.
 */
view?: SearchCatalogView;
/**
 * @minimum 1
 * @maximum 10000
 */
page?: number;
/**
 * @minimum 25
 * @maximum 50
 */
pageSize?: number;
/**
 * @maxLength 120
 */
manufacturer?: string;
/**
 * @maxLength 120
 */
form?: string;
registrationStatus?: SearchCatalogRegistrationStatus;
/**
 * @maxLength 180
 */
tradeName?: string;
/**
 * @maxLength 80
 */
strength?: string;
compositionType?: SearchCatalogCompositionType;
mappingStatus?: SearchCatalogMappingStatus;
nationalListStatus?: SearchCatalogNationalListStatus;
/**
 * @minimum 1
 * @maximum 10000
 */
groupPage?: number;
groupPageSize?: SearchCatalogGroupPageSize;
/**
 * @minimum 1
 * @maximum 10000
 */
tradePage?: number;
tradePageSize?: SearchCatalogTradePageSize;
/**
 * @minimum 1
 * @maximum 10000
 */
variantPage?: number;
variantPageSize?: SearchCatalogVariantPageSize;
/**
 * @maxLength 500
 */
groupKey?: string;
/**
 * @maxLength 240
 */
tradeNameKey?: string;
};

export type SearchCatalogType = typeof SearchCatalogType[keyof typeof SearchCatalogType];


export const SearchCatalogType = {
  all: 'all',
  ingredients: 'ingredients',
  registry_products: 'registry_products',
} as const;

export type SearchCatalogView = typeof SearchCatalogView[keyof typeof SearchCatalogView];


export const SearchCatalogView = {
  flat: 'flat',
  grouped: 'grouped',
} as const;

export type SearchCatalogRegistrationStatus = typeof SearchCatalogRegistrationStatus[keyof typeof SearchCatalogRegistrationStatus];


export const SearchCatalogRegistrationStatus = {
  active: 'active',
  terminated: 'terminated',
  unknown: 'unknown',
} as const;

export type SearchCatalogCompositionType = typeof SearchCatalogCompositionType[keyof typeof SearchCatalogCompositionType];


export const SearchCatalogCompositionType = {
  all: 'all',
  monotherapy: 'monotherapy',
  combination: 'combination',
  unknown: 'unknown',
} as const;

export type SearchCatalogMappingStatus = typeof SearchCatalogMappingStatus[keyof typeof SearchCatalogMappingStatus];


export const SearchCatalogMappingStatus = {
  all: 'all',
  approved: 'approved',
  unmapped: 'unmapped',
} as const;

export type SearchCatalogNationalListStatus = typeof SearchCatalogNationalListStatus[keyof typeof SearchCatalogNationalListStatus];


export const SearchCatalogNationalListStatus = {
  all: 'all',
  exact: 'exact',
  ingredient_only: 'ingredient_only',
  uncertain: 'uncertain',
  not_listed: 'not_listed',
} as const;

export type SearchCatalogGroupPageSize = typeof SearchCatalogGroupPageSize[keyof typeof SearchCatalogGroupPageSize];


export const SearchCatalogGroupPageSize = {
  NUMBER_10: 10,
  NUMBER_25: 25,
} as const;

export type SearchCatalogTradePageSize = typeof SearchCatalogTradePageSize[keyof typeof SearchCatalogTradePageSize];


export const SearchCatalogTradePageSize = {
  NUMBER_10: 10,
  NUMBER_25: 25,
} as const;

export type SearchCatalogVariantPageSize = typeof SearchCatalogVariantPageSize[keyof typeof SearchCatalogVariantPageSize];


export const SearchCatalogVariantPageSize = {
  NUMBER_10: 10,
  NUMBER_25: 25,
} as const;

export type GetProfessionalProductProfileParams = {
/**
 * @pattern ^[A-F0-9]{32}$
 */
productId: string;
/**
 * @pattern ^UA/\d+/\d+/\d+$
 */
registrationNumber: string;
/**
 * @pattern ^nszu-[a-f0-9]{24}$
 */
reimbursementPackageKey?: string;
/**
 * @pattern ^UA-\d{9}-\d{9}-\d{9}$
 */
priceCatalogId?: string;
};

export type CheckProductDispensingCategoryParams = {
/**
 * @pattern ^[A-F0-9]{32}$
 */
productId: string;
/**
 * @pattern ^UA/\d+/\d+/\d+$
 */
registrationNumber: string;
};

export type CheckProductSeriesRestrictionsParams = {
/**
 * @pattern ^[A-F0-9]{32}$
 */
productId: string;
/**
 * @pattern ^UA/\d+/\d+/\d+$
 */
registrationNumber: string;
/**
 * @minLength 1
 * @maxLength 80
 * @pattern ^[^\r\n]+$
 */
series: string;
};

export type GetExternalDrugReferenceParams = {
drugId?: string;
name?: string;
};

export type KnowledgeSearchParams = {
q: string;
skipExternal?: boolean;
};

export type NormalizeDrugNameParams = {
q: string;
};

export type ListReviewQueueParams = {
status?: ReviewQueueStatus;
conflictOnly?: boolean;
sourceId?: string;
locale?: string;
/**
 * @minimum 1
 * @maximum 100
 */
limit?: number;
/**
 * @minimum 0
 */
offset?: number;
};

